    render(
      <AppearanceProvider>
        <ConfirmProvider>
          <NeuronCard neuron={androidNeuron} live={true} brainId="brain1" brainName="Test Brain" onChanged={() => {}} />
        </ConfirmProvider>
      </AppearanceProvider>
    );
    // Android: memoryGb=6 -> (6-2)/2 = 2, cores=4 -> min(4,2,4)=2, but then because Android: n = Math.min(n, 1) -> 1 agent
